<?php require_once __DIR__.'/../includes/bootstrap.php';require_login();check_csrf();$s=db()->prepare('SELECT id FROM students WHERE user_id=?');$s->execute([actor_id()]);$sid=(int)$s->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'&&$sid){db()->prepare('INSERT INTO internships(student_id,company_name,role,start_date,end_date,status,remarks) VALUES(?,?,?,?,?,\'Pending\',?)')->execute([$sid,$_POST['company_name'],$_POST['role'],$_POST['start_date'],$_POST['end_date'],$_POST['remarks']]);$_SESSION['flash']=['success','Internship submitted for verification'];redirect('internships.php');}$r=db()->prepare('SELECT * FROM internships WHERE student_id=? ORDER BY id DESC');$r->execute([$sid]);page_top('Internship Center');flash();if(has_role('Student')):?><div class='card p-4 mb-4'><form method='post' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><div class='col-md-4'><input name='company_name' class='form-control' placeholder='Company' required></div><div class='col-md-4'><input name='role' class='form-control' placeholder='Role' required></div><div class='col-md-2'><input name='start_date' type='date' class='form-control' required></div><div class='col-md-2'><input name='end_date' type='date' class='form-control' required></div><div class='col-12'><textarea name='remarks' class='form-control' placeholder='Notes'></textarea></div><button class='btn btn-primary col-md-2'>Submit Internship</button></form></div><?php endif;?><div class='card p-3 table-responsive'><table class='table'><tr><th>Company</th><th>Role</th><th>Dates</th><th>Status</th></tr><?php foreach($r as $x):?><tr><td><?=e($x['company_name'])?></td><td><?=e($x['role'])?></td><td><?=e($x['start_date'])?> → <?=e($x['end_date'])?></td><td><?=e($x['status'])?></td></tr><?php endforeach;?></table></div><?php page_bottom();
